action.command:
cat > /tmp/scan3.mjs <<'EOF'
import fs from "fs";
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
let count=0;
for (let n=0;n<lines.length && count<40;n++){
  const m = lines[n];
  if (m.includes('trustPolicy') && (m.includes('"no-downgrade"') || m.includes('default') || m.includes('Default'))) {
    console.log(n, m.trim().slice(0,150)); count++;
  }
}
EOF
node /tmp/scan3.mjs | head -30

